const DEMO='https://meftah7.github.io/myhealthcare_v2/';
// Add a local MP4 path or an HTTPS MP4 URL here when the walkthrough is ready.
const WALKTHROUGH_VIDEO='';
const icons={calendar:'<rect x="3" y="5" width="18" height="16" rx="3"/><path d="M7 3v4m10-4v4M3 11h18m-13 5h3"/>',record:'<rect x="5" y="3" width="14" height="18" rx="2"/><path d="M9 8h6m-6 4h6m-6 4h4"/>',heart:'<path d="M20.8 4.6a5.5 5.5 0 0 0-7.8 0L12 5.7l-1.1-1.1a5.5 5.5 0 0 0-7.8 7.8L12 21l8.8-8.6a5.5 5.5 0 0 0 0-7.8Z"/>',people:'<circle cx="9" cy="8" r="3"/><path d="M3 21v-3a6 6 0 0 1 12 0v3m2-16a3 3 0 0 1 0 6m2 4a5 5 0 0 1 2 4v2"/>',chat:'<path d="M21 11.5a8.4 8.4 0 0 1-.9 3.8A8.5 8.5 0 0 1 12.5 20a8.4 8.4 0 0 1-3.8-.9L3 21l1.9-5.7a8.4 8.4 0 0 1-.9-3.8A8.5 8.5 0 0 1 8.7 3.9a8.4 8.4 0 0 1 3.8-.9h.5a8.5 8.5 0 0 1 8 8v.5Z"/>',shield:'<path d="m12 3 8 4v5c0 5-8 9-8 9s-8-4-8-9V7l8-4Z"/><path d="m8 12 3 3 5-6"/>',globe:'<circle cx="12" cy="12" r="9"/><path d="M3 12h18M12 3c5 5 5 13 0 18-5-5-5-13 0-18Z"/>',spark:'<path d="m12 3 2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5L12 3Z"/>',play:'<path d="m9 5 11 7-11 7V5Z"/>',mail:'<rect x="3" y="5" width="18" height="14" rx="2"/><path d="m3 6 9 7 9-7"/>'};
function svg(n){return `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[n]||icons.heart}</svg>`}function icon(n,green=false){return `<span class="icon ${green?'green':''}">${svg(n)}</span>`}function phone(img='home'){return `<div class="phone"><img src="assets/${img}.png" alt="Actual myhealth ${img==='home'?'patient home':img==='records'?'health records':'doctor search'} screen" loading="lazy"></div>`}function brand(){return '<a class="brand" href="index.html"><img src="assets/logo.png" alt="">myhealth</a>'}const page=document.body.dataset.page||'home';
const nav=[['home','Home','index.html'],['about','About us','about.html'],['services','Solutions','services.html'],['features','Features','features.html'],['demo','Demo','demo.html'],['contact','Contact','contact.html']];
document.querySelector('header').innerHTML=`<div class="wrap header">${brand()}<nav class="nav" id="navigation" aria-label="Main navigation">${nav.map(([key,label,url])=>`<a href="${url}" class="${page===key?'active':''}" ${page===key?'aria-current="page"':''}>${label}</a>`).join('')}</nav><a class="btn small" href="${DEMO}" target="_blank" rel="noopener">Try the app</a><button class="menu" aria-expanded="false" aria-controls="navigation">Menu</button></div>`;
document.querySelector('footer').innerHTML=`<div class="wrap"><div class="footer-grid"><div>${brand()}<p>A clearer view of your health.<br>A closer connection to your care.</p></div><div><h4>Discover</h4><a href="about.html">Our story</a><a href="services.html">Our solutions</a><a href="features.html">Product features</a></div><div><h4>Explore</h4><a href="demo.html">Try the demo</a><a href="demo.html#walkthrough">Video walkthrough</a><a href="https://github.com/Meftah7/myhealthcare_v2" target="_blank" rel="noopener">GitHub project</a></div><div><h4>Let’s connect</h4><a href="mailto:myhealthcare.bh@gmail.com">myhealthcare.bh@gmail.com</a><a href="contact.html">Contact the team</a><span class="linkedin" role="img" aria-label="LinkedIn">in</span><span class="status-text">Coming soon</span></div></div><div class="footer-bottom"><span>© ${new Date().getFullYear()} myhealth. Built with care in Bahrain.</span><span>University of Bahrain · College of Information Technology</span></div></div>`;
function intro(tag,title,desc){return `<section class="page-intro"><div class="wrap"><span class="eyebrow">${tag}</span><h1>${title}</h1><p>${desc}</p></div></section>`}function cta(){return `<section class="section"><div class="wrap"><div class="cta"><div><h2>Better care starts with connection.</h2><p>Take a look inside myhealth and explore it for yourself.</p></div><div class="buttons"><a class="btn" href="demo.html">Explore the demo</a></div></div></div></section>`}function video(){return `<section class="section video-section" id="walkthrough"><div class="wrap"><div class="section-head"><div><span class="eyebrow">See it in action</span><h2>A little tour.<br>A clearer picture.</h2></div><p>From booking a visit to understanding a report, see how myhealth fits into everyday care.</p></div>${WALKTHROUGH_VIDEO?`<video class="video-box" controls preload="metadata" style="width:100%" aria-label="myhealth product walkthrough"><source src="${WALKTHROUGH_VIDEO}" type="video/mp4">Your browser does not support embedded video.</video>`:`<div class="video-box"><div class="video-content"><span class="play">${svg('play')}</span><h3>Your myhealth walkthrough</h3><p>A guided look at the app is on its way.<br>You can explore the live demo today.</p><span class="badge">VIDEO COMING SOON</span></div></div>`}<div class="video-caption"><span>Meet the patient, staff, and admin experiences.</span><a href="${DEMO}" target="_blank" rel="noopener">Explore the live app while you wait</a></div></div></section>`}
const solutions=[['heart','For patients','Your health, easier to manage.','Keep your records close, find a clinician, book a visit, and stay connected with your care team.'],['people','For care teams','More clarity. Better coordination.','Bring schedules, patient charts, consultations, and everyday clinical work into a connected workspace.'],['shield','For administrators','A clearer view of the clinic.','Organize staff, departments, appointments, billing, and the work that keeps a clinic running.']];
function solutionCards(){return `<div class="cards">${solutions.map(([i,k,h,p])=>`<article class="card">${icon(i)}<p style="font-size:12px;font-weight:700;letter-spacing:.1em;text-transform:uppercase;margin:24px 0 10px;color:var(--blue)">${k}</p><h3>${h}</h3><p>${p}</p><a class="text-link" href="services.html">Explore this solution</a></article>`).join('')}</div>`}
const home=`<section class="hero"><div class="wrap hero-grid"><div><span class="eyebrow">Connected care, made simple</span><h1>Your health.<br>Your care team.<br><em>All together.</em></h1><p>Health records, appointments, and the people who care for you — brought together in one easy-to-use place.</p><div class="buttons"><a class="btn teal" href="demo.html">Explore myhealth</a><a class="btn outline" href="#walkthrough">${svg('play').replace('<svg','<svg width="18" height="18"')} View walkthrough</a></div><p class="hero-note">Built in Bahrain <span></span> English & Arabic <span></span> Designed around you</p></div><div class="hero-visual"><div class="halo"></div>${phone()}<div class="float-card one">${icon('calendar',true)}<div><b>Your next visit, organized</b><small>Appointments in one place</small></div></div><div class="float-card two">${icon('record')}<div><b>A clearer health story</b><small>Records that stay together</small></div></div></div></div></section><div class="proof"><div class="wrap proof-inner"><span>Thoughtfully connected.</span><div class="proof-item">${svg('record')} Personal health records</div><div class="proof-item">${svg('people')} Dedicated care workspaces</div><div class="proof-item">${svg('globe')} English & Arabic</div></div></div><section class="section"><div class="wrap"><div class="section-head"><div><span class="eyebrow">One platform. Every perspective.</span><h2>Care works better<br>when it comes together.</h2></div><p>Different people. Different needs. One shared goal: make the next step in care easier.</p></div>${solutionCards()}</div></section><section class="section soft"><div class="wrap split"><div class="feature-visual">${phone('records')}<div class="float-card">${icon('shield',true)}<div><b>Your story, in one place</b><small>Reports, results & medications</small></div></div></div><div><span class="eyebrow">Less searching. More understanding.</span><h2>Make sense of<br>your health story.</h2><p>Bring your medical information together so the details you need are easier to find, follow, and discuss.</p><div class="tabs" role="tablist" aria-label="Explore health features"><button class="tab selected" role="tab" aria-selected="true" data-tab="records">Health records</button><button class="tab" role="tab" aria-selected="false" data-tab="reports">Report support</button><button class="tab" role="tab" aria-selected="false" data-tab="visits">Appointments</button></div><div id="feature-panel" role="tabpanel"></div><a class="text-link" href="features.html">Discover all features</a></div></div></section><section class="section"><div class="wrap"><div class="center"><span class="eyebrow">A simpler journey</span><h2>From the first visit<br>to the next step.</h2><p>myhealth keeps the important parts of your care within reach.</p></div><div class="steps"><article>${icon('people')}<h3>Find your care</h3><p>Explore clinicians and choose an available appointment that works for you.</p></article><article>${icon('record')}<h3>Keep the details together</h3><p>Find your health records, documents, and visit information in your account.</p></article><article>${icon('chat',true)}<h3>Stay connected</h3><p>Use care-team messages and report support to understand what comes next.</p></article></div></div></section>${video()}${cta()}`;
const about=`${intro('About myhealth','Built around people.<br>Connected by care.','We believe managing healthcare should feel clearer, more organized, and easier to navigate.')}<section class="section"><div class="wrap split"><div><span class="eyebrow">Our story</span><h2>Good care needs<br>a clear picture.</h2></div><div><p>Appointments in one place. Reports somewhere else. Important details spread across different conversations. myhealth brings these parts of care together.</p><p>Developed at the University of Bahrain, our project explores how a connected application can support patients, healthcare teams, and clinic administrators.</p></div></div></section><section class="section soft"><div class="wrap cards"><article class="card">${icon('heart')}<h3>Our mission</h3><p>Make health information and everyday care tasks easier to access, understand, and organize.</p></article><article class="card">${icon('globe')}<h3>Our vision</h3><p>A healthcare experience where people and their care teams have a clearer connection to the information they need.</p></article><article class="card">${icon('people',true)}<h3>Our focus</h3><p>Bring records together, simplify appointment journeys, and support the people coordinating care.</p></article></div></section><section class="section"><div class="wrap"><div class="section-head"><div><span class="eyebrow">The people behind myhealth</span><h2>A shared idea.<br>A dedicated team.</h2></div><p>Computer science students turning a practical healthcare challenge into a connected product experience.</p></div><div class="team"><article class="card"><div class="avatar">AJ</div><h3>Ali Mohamed Jaafar Mohamed</h3><p>Co-developer · University of Bahrain</p><span class="linkedin" role="img" aria-label="LinkedIn">in</span><span class="status-text">Profile coming soon</span></article><article class="card"><div class="avatar">MM</div><h3>Mohammed A.Redha Meftah</h3><p>Co-developer · University of Bahrain</p><span class="linkedin" role="img" aria-label="LinkedIn">in</span><span class="status-text">Profile coming soon</span></article></div><p class="small-note center" style="margin-top:28px!important">Supervised by Dr. Amal Ghanim · College of Information Technology</p></div></section>${cta()}`;
const services=`${intro('Solutions for connected care','Made for everyone<br>in the care journey.','Explore the ways myhealth supports patients, clinical teams, and the people managing everyday clinic operations.')}<section class="section"><div class="wrap">${solutionCards()}<div class="split" style="margin-top:80px"><div><span class="eyebrow">Patient experience</span><h2>A home for your<br>health information.</h2><p>Bring appointments, reports, medications, and care conversations together in one familiar experience.</p><ul class="checks"><li>Find clinicians and book available appointments</li><li>Browse health records and original documents</li><li>Review vitals, medication details, and visit history</li><li>Connect with your clinician through care messages</li></ul><a class="btn" href="demo.html">Explore the patient demo</a></div><div class="feature-visual">${phone()}</div></div></div></section><section class="section soft"><div class="wrap"><span class="eyebrow">Care-team workspaces</span><h2>The right tools<br>for each role.</h2><div class="cards">${[['Doctor','Schedules, patient charts, consultations, prescriptions, and clinical documentation.'],['Nurse','Assigned intake work, patient observations, vitals, and coordination with the care team.'],['Receptionist','Patient lookup, appointment coordination, check-in, and supported document-desk work.'],['Pharmacist','Prescription queues, medicine stock, dispensing records, and clarification workflows.'],['Dentist','Appointment schedules, patient charts, consultations, and a dedicated dental chart.'],['Administrator','Account and department management, appointments, billing, and clinic oversight.']].map(([h,p])=>`<article class="card"><h3>${h}</h3><p>${p}</p></article>`).join('')}</div></div></section>${cta()}`;
const features=`${intro('Product features','Small details.<br>A more connected experience.','Practical tools that help you organize appointments, understand records, and keep care moving.')}<section class="section"><div class="wrap"><div class="feature-row"><div class="feature-visual">${phone('booking')}</div><div><span class="eyebrow">Appointments</span><h2>Find the right visit.<br>Keep the details close.</h2><p>Browse clinicians, review available times, and follow a clear booking journey.</p><ul class="checks"><li>Clinician and appointment discovery</li><li>Appointment confirmation and ticket details</li><li>Upcoming visits and appointment history</li></ul></div></div><div class="feature-row"><div class="feature-visual">${phone('records')}</div><div><span class="eyebrow">Health records</span><h2>Your records,<br>with more context.</h2><p>Keep medical reports, medications, imaging, and visit information organized around the patient.</p><ul class="checks"><li>Original PDF reports and document access</li><li>Health history and vitals trends</li><li>Information linked to the right patient</li></ul></div></div><div class="cards">${[['spark','Plain-language report support','Upload a medical PDF and explore explanations and follow-up questions when the report AI service is connected.'],['chat','Care-team conversations','Keep patient–clinician messages together and give staff a dedicated place for team communication.'],['record','Medical documents','Supported document workflows include preparation, issuance, downloads, and verification.'],['globe','English and Arabic','Language options and right-to-left layouts help make the application easier to use.'],['people','Workspaces by role','Patient, staff, and admin experiences organize tools around the work each person needs to do.'],['heart','Personal preferences','Responsive navigation, light and dark themes, and text-size options support different preferences.']].map(([i,h,p])=>`<article class="card">${icon(i)}<h3>${h}</h3><p>${p}</p></article>`).join('')}<div class="demo-note" style="grid-column:1/-1">The demonstration uses sample data. Feature availability depends on the app’s operating mode and connected services. AI report support is informational and requires review; it does not provide a diagnosis.</div></div></div></section>${cta()}`;
const demo=`${intro('Experience myhealth','Take a look inside.<br>Make yourself at home.','Explore a working demonstration with sample accounts for patients, clinical staff, and administrators.')}<section class="section"><div class="wrap split"><div><span class="eyebrow">Live application</span><h2>Your first look<br>at connected care.</h2><p>Open the app, choose a demo role on the sign-in screen, and explore its workspace. Start with Patient for a guided first impression of everyday care.</p><div class="buttons"><a class="btn" href="${DEMO}" target="_blank" rel="noopener">Launch live demo</a><a class="btn outline" href="https://github.com/Meftah7/myhealthcare_v2" target="_blank" rel="noopener">View on GitHub</a></div><div class="demo-note">Use the <strong>Demo accounts</strong> buttons to sign in. The hosted app uses synthetic records stored in your browser. Switch roles in the same browser to explore the same demonstration data. Please use sample information only.</div></div><div class="feature-visual">${phone()}</div></div></section>${video()}<section class="section"><div class="wrap"><span class="eyebrow">Things to explore</span><h2>Three ways to experience myhealth.</h2><div class="steps"><article>${icon('heart')}<h3>As a patient</h3><p>Browse records, find a doctor, explore appointments, and open the Care Navigator.</p></article><article>${icon('people')}<h3>As a staff member</h3><p>Open a schedule, review a patient chart, and discover the workspace for each clinical role.</p></article><article>${icon('shield')}<h3>As an administrator</h3><p>Explore clinic accounts, appointments, departments, and administrative tools.</p></article></div><div class="faq" style="margin-top:50px"><details><summary>Do I need to create an account?</summary><p>No. Choose one of the demo-account shortcuts on the app’s sign-in screen.</p></details><details><summary>Does the demo use real patient information?</summary><p>No. The hosted demonstration uses synthetic data and browser-local storage.</p></details><details><summary>Are live AI and payments connected?</summary><p>Live report AI needs a configured service. The payment demonstration is simulated and does not move real money.</p></details></div></div></section>`;
const contact=`${intro('Contact us','Let’s talk about<br>better-connected care.','Have a question, an idea, or feedback on the demonstration? We would like to hear from you.')}<section class="section"><div class="wrap contact-grid"><div><span class="eyebrow">Get in touch</span><h2>A conversation<br>starts here.</h2><div class="detail">${icon('mail')}<h3>Email the team</h3><a class="text-link" href="mailto:myhealthcare.bh@gmail.com">myhealthcare.bh@gmail.com</a></div><div class="detail"><h3>Based in Bahrain</h3><p>University of Bahrain<br>College of Information Technology</p></div><div class="detail"><h3>Follow our journey</h3><span class="linkedin" role="img" aria-label="LinkedIn">in</span><span class="status-text">LinkedIn profile coming soon</span></div></div><form class="form" id="contact-form"><h3>Send us a message</h3><p style="color:var(--muted);font-size:15px">Tell us what you have in mind.</p><label for="name">Your name</label><input id="name" name="name" autocomplete="name" required maxlength="100" placeholder="Your full name"><label for="email">Email address</label><input id="email" name="email" type="email" autocomplete="email" required placeholder="you@example.com"><label for="message">Your message</label><textarea id="message" name="message" required maxlength="4000" placeholder="How can we help?"></textarea><button class="btn" type="submit">Open email draft</button><p class="small-note">This opens your email app with your message ready to send to our team.</p><p id="form-status" role="status" class="small-note"></p></form></div></section>`;
document.querySelector('main').innerHTML=({home,about,services,features,demo,contact})[page]||home;
document.querySelector('.menu').addEventListener('click',e=>{const open=document.querySelector('.nav').classList.toggle('open');e.currentTarget.setAttribute('aria-expanded',String(open));});
const panel=document.getElementById('feature-panel');const panels={records:'<ul class="checks"><li>Reports, medications, and visit details together</li><li>Original documents when you need them</li><li>A timeline that helps you follow your care</li></ul>',reports:'<ul class="checks"><li>Upload and keep your original medical PDF</li><li>Explore a plain-language report explanation</li><li>Ask report questions when live AI is connected</li></ul>',visits:'<ul class="checks"><li>Discover clinicians and available appointments</li><li>Review the details before you confirm</li><li>Keep upcoming visits and tickets close</li></ul>'};if(panel){panel.innerHTML=panels.records;document.querySelectorAll('.tab').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('.tab').forEach(t=>{t.classList.toggle('selected',t===b);t.setAttribute('aria-selected',String(t===b))});panel.innerHTML=panels[b.dataset.tab]}));}
document.getElementById('contact-form')?.addEventListener('submit',e=>{e.preventDefault();const f=new FormData(e.currentTarget);const body=`Name: ${f.get('name')}\nEmail: ${f.get('email')}\n\n${f.get('message')}`;location.href=`mailto:myhealthcare.bh@gmail.com?subject=${encodeURIComponent('myhealth website enquiry')}&body=${encodeURIComponent(body)}`;document.getElementById('form-status').textContent='Your email draft is ready. Send it from your email app, or email us directly using the address shown here.';});
